import { dataset, dimension, divide, gte, measure, nullIfZero } from '@hypequery/datasets';

const DAY_GRAINS = ['day', 'week', 'month', 'quarter', 'year'] as const;

/** The raw fact table: a million rows, aggregated at query time. */
export const Events = dataset('events', {
  source: 'events',
  timeKey: 'occurred_at',
  dimensions: {
    eventId: dimension.number({ column: 'event_id' }),
    occurredAt: dimension.timestamp({ column: 'occurred_at' }),
    tenantId: dimension.number({ column: 'tenant_id' }),
    userId: dimension.number({ column: 'user_id' }),
    eventType: dimension.string({ column: 'event_type' }),
    statusCode: dimension.number({ column: 'status_code' }),
  },
  measures: {
    events: measure.count('eventId'),
    uniqueUsers: measure.countDistinct('userId'),
    errors: measure.count('statusCode', { filters: [gte('statusCode', 500)] }),
    errorRate: measure.derived({
      uses: { errors: 'errors', events: 'events' },
      formula: ({ errors, events }) => divide(errors, nullIfZero(events)),
    }),
  },
});

/**
 * Incremental rollup (sql/01-incremental.sql). Reads aggregate states, so
 * `measure.merge` applies `uniqExactMerge` and uniques stay exact at any grain.
 */
export const EventsDaily = dataset('eventsDaily', {
  source: 'events_daily',
  timeKey: 'day',
  timeGrains: [...DAY_GRAINS],
  dimensions: {
    day: dimension.timestamp(),
    tenantId: dimension.number({ column: 'tenant_id' }),
    eventType: dimension.string({ column: 'event_type' }),
  },
  measures: {
    events: measure.sum('events'),
    errors: measure.sum('errors'),
    uniqueUsers: measure.merge('uniqExact', 'users'),
    errorRate: measure.derived({
      uses: { errors: 'errors', events: 'events' },
      formula: ({ errors, events }) => divide(errors, nullIfZero(events)),
    }),
  },
});

/**
 * Refreshable rollup (sql/02-refreshable.sql). Final values per tenant-day,
 * including a JOIN to `tenants` and an exact p95, recomputed every hour.
 */
export const TenantDailySummary = dataset('tenantDailySummary', {
  source: 'tenant_daily_summary',
  timeKey: 'day',
  timeGrains: [...DAY_GRAINS],
  dimensions: {
    day: dimension.timestamp(),
    tenantId: dimension.number({ column: 'tenant_id' }),
    tenantName: dimension.string({ column: 'tenant_name' }),
    plan: dimension.string(),
  },
  measures: {
    events: measure.sum('events'),
    errors: measure.sum('errors'),
    worstP95LatencyMs: measure.max('p95_latency_ms', { label: 'Worst daily p95 latency (ms)' }),
    errorRate: measure.derived({
      uses: { errors: 'errors', events: 'events' },
      formula: ({ errors, events }) => divide(errors, nullIfZero(events)),
    }),
  },
});

import { createMCPServer } from '@hypequery/mcp';
import { publishDatasets } from '@hypequery/datasets';
import { analytics } from '../analytics/client.js';
import { Events, Subscriptions } from '../analytics/datasets.js';

/**
 * A governed MCP server over the seed dataset.
 *
 * The agent gets exactly four tools: list_datasets, get_dataset_schema,
 * query_dataset and query_metric. It can only reach the datasets published
 * here, with the dimensions and measures they declare; generated SQL is
 * redacted; and because both datasets have a tenantKey, every query is
 * scoped to the tenant this process was started for. The tenant comes from
 * the environment the MCP client launches the server with, never from the
 * agent.
 */
const tenantId = process.env.TENANT_ID;
if (!tenantId) {
  console.error('Set TENANT_ID to the tenant this server is allowed to see, e.g. TENANT_ID=153.');
  process.exit(2);
}

export const datasets = publishDatasets().publish(Events).publish(Subscriptions).build();

await createMCPServer({
  datasets,
  analytics,
  tenantId,
  name: 'hypequery-seed-analytics',
  version: '0.1.0',
  // Only turn on in a trusted debugging session: it puts SQL in tool results.
  includeSql: process.env.HYPEQUERY_MCP_INCLUDE_SQL === '1',
});
// The server now speaks MCP over stdio until the client closes the pipe.

import { createAnalyticsTokenIssuer, createJwtStrategy, initServe } from '@hypequery/serve';
import { db } from './client.js';
import { Events } from './datasets.js';

/**
 * Embedded analytics, tenant-scoped end to end.
 *
 * 1. Your app authenticates the user and mints a short-lived analytics token
 *    (`issueAnalyticsToken`) whose `org_id` claim is the tenant.
 * 2. The embed sends that token as a Bearer header.
 * 3. serve verifies it (`createJwtStrategy`), extracts the tenant, and every
 *    dataset query is scoped by `tenantKey` before it reaches ClickHouse.
 */
export const AUTH = {
  secret: process.env.HYPEQUERY_AUTH_SECRET ?? 'demo-only-change-me-7c9a4b1f2e3d',
  issuer: 'https://embedded-analytics.example',
  audience: 'hypequery-analytics',
};

/** Mint on your server, in a route that already knows who the user is. */
export const issueAnalyticsToken = createAnalyticsTokenIssuer({
  ...AUTH,
  expiresIn: '15m',
});

const { serve } = initServe({
  context: () => ({ db }),
  auth: createJwtStrategy(AUTH), // sub → userId, org_id → tenantId, roles, scopes
  basePath: '/api/analytics',
});

export const api = serve({
  queryBuilder: db,
  tenant: {
    extract: (auth) => auth.tenantId,
    required: true, // no tenant, no query
  },
  datasets: {
    events: { dataset: Events, requiredScopes: ['read:analytics'], maxLimit: 200, cache: 10_000 },
  },
});

import { dataset, dimension, divide, gte, measure, nullIfZero } from '@hypequery/datasets';

/**
 * multiIf(cond1, then1, cond2, then2, ..., else) returns the value of the
 * first condition that is true. Defined once here, the buckets mean the same
 * thing on every dashboard, API and agent that queries the dataset.
 *
 * Buckets are half-open ([100, 250) and so on): `latency_ms < 250` puts a
 * 250 ms request in the next bucket up. Labels do not sort in bucket order,
 * so a numeric `latencyBucketOrder` from the same conditions travels with them.
 */
const LATENCY_BUCKET = `multiIf(latency_ms < 100, '< 100 ms', latency_ms < 250, '100-250 ms', latency_ms < 500, '250-500 ms', latency_ms < 1000, '500 ms-1 s', '>= 1 s')`;

const LATENCY_BUCKET_ORDER = `multiIf(latency_ms < 100, 1, latency_ms < 250, 2, latency_ms < 500, 3, latency_ms < 1000, 4, 5)`;

// Order matters: 429 is also >= 400, so it must be tested first.
const STATUS_CLASS = `multiIf(status_code >= 500, 'server_error', status_code = 429, 'rate_limited', status_code >= 400, 'client_error', 'ok')`;

export const Requests = dataset('requests', {
  source: 'events',
  timeKey: 'occurred_at',
  dimensions: {
    eventId: dimension.number({ column: 'event_id' }),
    occurredAt: dimension.timestamp({ column: 'occurred_at' }),
    statusCode: dimension.number({ column: 'status_code' }),
    latencyMs: dimension.number({ column: 'latency_ms' }),
    latencyBucket: dimension.string({ sql: LATENCY_BUCKET, dependencies: ['latency_ms'], label: 'Latency bucket' }),
    latencyBucketOrder: dimension.number({ sql: LATENCY_BUCKET_ORDER, dependencies: ['latency_ms'], label: 'Latency bucket order' }),
    statusClass: dimension.string({ sql: STATUS_CLASS, dependencies: ['status_code'], label: 'Status class' }),
  },
  measures: {
    requests: measure.count('eventId', { label: 'Requests' }),
    serverErrors: measure.count('eventId', { label: 'Server errors', filters: [gte('statusCode', 500)] }),
    serverErrorRate: measure.derived({
      label: 'Server error rate',
      uses: { errors: 'serverErrors', requests: 'requests' },
      formula: ({ errors, requests }) => divide(errors, nullIfZero(requests)),
    }),
  },
});

