'use client';

import { useState } from 'react';
import { BreakdownBars } from './breakdown-bars';
import { KpiTiles } from './kpi-tiles';
import { Timeseries } from './timeseries';
import {
  clearSelections,
  initialState,
  RANGE_PRESETS,
  rangeEndingAt,
  SEED_LAST_DAY,
  toDatasetFilters,
  toggleSelection,
  type CrossFilterState,
  type Dimension,
} from '@/lib/filters';

/**
 * The dashboard owns one piece of state: the date range plus the current
 * selections. Every panel derives its own dataset filters from it, so a click
 * in one panel re-queries all the others through the same `events` endpoint.
 */
export function Dashboard() {
  const [state, setState] = useState<CrossFilterState>(initialState);
  const select = (dimension: Dimension, value: string) =>
    setState((current) => toggleSelection(current, dimension, value));
  const activeDays = Math.round(
    (Date.parse(`${state.range.to}T00:00:00Z`) - Date.parse(`${state.range.from}T00:00:00Z`)) / 86_400_000,
  ) + 1;
  const selections = Object.entries(state.selections) as Array<[Dimension, string]>;

  return (
    <>
      <div className="toolbar" role="toolbar" aria-label="Filters">
        {RANGE_PRESETS.map((preset) => (
          <button
            key={preset.days}
            type="button"
            className="chip"
            aria-pressed={activeDays === preset.days}
            onClick={() => setState((current) => ({ ...current, range: rangeEndingAt(SEED_LAST_DAY, preset.days) }))}
          >
            Last {preset.label}
          </button>
        ))}
        <span className="spacer" />
        {selections.map(([dimension, value]) => (
          <button key={dimension} type="button" className="chip selection" onClick={() => select(dimension, value)}>
            {dimension}: {value} ×
          </button>
        ))}
        {selections.length > 0 && (
          <button type="button" className="chip" onClick={() => setState(clearSelections)}>
            Clear all
          </button>
        )}
      </div>

      <div className="grid">
        <KpiTiles filters={toDatasetFilters(state)} />
        <Timeseries filters={toDatasetFilters(state)} />
        <BreakdownBars
          title="Events by type"
          dimension="eventType"
          filters={toDatasetFilters(state, 'eventType')}
          selected={state.selections.eventType}
          onSelect={(value) => select('eventType', value)}
        />
        <BreakdownBars
          title="Events by device"
          dimension="device"
          filters={toDatasetFilters(state, 'device')}
          selected={state.selections.device}
          onSelect={(value) => select('device', value)}
        />
      </div>
    </>
  );
}

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { between, type DatasetQueryFor } from '@hypequery/datasets';
import { analytics, db } from './client.js';
import { Events } from './dataset.js';

/** The seed's last full week; fixed so the output is reproducible. */
export const RANGE: [string, string] = ['2026-10-25 00:00:00', '2026-10-31 23:59:59'];

/**
 * The question: for each event type over the last week, how many requests
 * were there and what were the p50, p95 and p99 latencies? Slowest first.
 */
export const query = {
  dimensions: ['eventType'],
  measures: ['events', 'p50LatencyMs', 'p95LatencyMs', 'p99LatencyMs'],
  filters: [between('occurredAt', RANGE[0], RANGE[1])],
  orderBy: [{ field: 'p95LatencyMs', direction: 'desc' }],
} satisfies DatasetQueryFor<typeof Events>;

export function toSQL(): string {
  return analytics.toSQL(Events, query);
}

export async function run() {
  const result = await analytics.execute(Events, query);
  return result.data;
}

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const isMain = process.argv[1] && import.meta.url === new URL(`file://${process.argv[1]}`).href;
if (isMain) {
  run()
    .then(async (rows) => {
      if (process.argv.includes('--write')) {
        // Capture the artifacts shown on the recipe page and asserted in CI.
        fs.writeFileSync(path.join(root, 'expected.sql'), `${toSQL()}\n`);
        fs.writeFileSync(path.join(root, 'output.json'), `${JSON.stringify(rows, null, 2)}\n`);
        console.log('wrote expected.sql and output.json');
      } else if (process.argv.includes('--json')) {
        console.log(JSON.stringify(rows, null, 2));
      } else {
        console.log(`p95 latency per event type, ${RANGE[0].slice(0, 10)} to ${RANGE[1].slice(0, 10)}\n`);
        console.table(rows);
        console.log('\nGenerated SQL:\n' + toSQL());
      }
      await db.close();
    })
    .catch(async (error) => {
      console.error(error instanceof Error ? error.message : error);
      await db.close();
      process.exit(1);
    });
}

